return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Отидете на Търсене на плъгини','Activate %s' => 'Активиране на %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> изисква <strong>%2$s</strong> да бъде инсталиран и активиран. <a href="%4$s">%3$s</a>','Enter your code here' => 'Въведете кода си тук','Add %s' => 'Добавяне на %s','Remove' => 'Премахване на','Order number and receipt will be sent to this email address.' => 'Номерът на поръчката и разписката ще бъдат изпратени на този имейл адрес.','Apartment, unit, building, floor, etc.' => 'Апартамент, блок, сграда, етаж и т.н.','Shipping phone' => 'Телефон за доставка','Only used for shipping-related questions.' => 'Използва се само за въпроси, свързани с доставката.','Single step' => 'Единична стъпка','Click to go to the order summary' => 'Кликнете, за да преминете към обобщението на поръчката','Cart total:' => 'Обща стойност на количката:','Proceed to %s' => 'Продължете към %s','Proceed to contact' => 'Преминете към контакт','Proceed to shipping' => 'Преминаване към изпращане','Proceed to billing' => 'Преминаване към фактуриране','Proceed to payment' => 'Преминаване към плащане','Shipping method' => 'Метод на доставка','Additional notes' => 'Допълнителни бележки','Payment method' => 'Метод на плащане','Step %1$s of %2$s' => 'Стъпка %1$s от %2$s','Change: %s' => 'Промяна: %s','Not selected yet.' => 'Все още не е избран.','Same as shipping address' => 'Същият като адреса за доставка','Same as billing address' => 'Същият като адреса за фактуриране','Order summary' => 'Резюме на поръчката','Edit cart' => 'Редактиране на количката','Did you mean %s?' => 'Искахте да кажете %s?','Change email address to: {suggestion-value}' => 'Променете имейл адреса на: {стойност на предложението}','This is a required field.' => 'Това е задължително поле.','This is not a valid email address.' => 'Това не е валиден имейл адрес.','This field does not match the related field value.' => 'Това поле не съвпада със стойността на свързаното поле.','The CPF number "{cpf_number}" is invalid.' => 'Номерът на CPF "{cpf_number}" е невалиден.','The CNPJ number "{cnpj_number}" is invalid.' => 'Номерът на CNPJ "{cnpj_number}" е невалиден.','(Required)' => '(Задължително)','Checkout Header - Desktop' => 'Заглавие на касата - Настолен компютър','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Показване на уиджети в заглавието на касата за големи екрани. Показва се само ако използвате заглавието на касата на плъгина.','Checkout Header - Mobile' => 'Заглавие на касата - мобилно','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Показвайте уиджети под заглавието на касата за мобилни устройства. Показва се само ако използвате заглавието на касата на плъгина.','Checkout Sidebar' => 'Странична лента на касата','Display widgets on the checkout sidebar after the order summary.' => 'Показване на уиджети в страничната лента на касата след обобщението на поръчката.','Checkout Order Summary' => 'Обобщение на поръчката на касата','Display widgets inside the order summary at the checkout page.' => 'Показване на уиджети в обобщението на поръчката в страницата за плащане.','Checkout Below Place Order' => 'Поръчайте по-долу Място за поръчка','Display widgets below the place order button at the checkout page.' => 'Показване на уиджети под бутона за поръчка в страницата за плащане.','Checkout Footer' => 'Краен колонтитул на касата','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Показване на уиджети в долния колонтитул на касата. Показва се само ако използвате долния колонтитул на плъгина.','Classic' => 'Класически','Boxed' => 'В кутия','Split' => 'Сплит','Minimalist' => 'Минималистичен','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Плъзгащи се плъгини за проверка и дата на доставка от CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Открихме, че използвате плъгините Delivery & Pickup Date Time за WooCommerce (безплатни и PRO) от CodeRockz. Интеграцията с тези плъгини е преместена в Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Надграждане до PRO','Fluid Checkout database updated successfully' => 'Базата данни на Fluid Checkout е актуализирана успешно','The database changes where applied successfully.' => 'Промените в базата данни са приложени успешно.','Dismiss' => 'Отхвърляне на','Fluid Checkout database update' => 'Актуализация на базата данни на Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Необходими са някои промени в базата данни. Както при всяка актуализация, препоръчваме ви да <strong>изготвите пълно резервно копие на уебсайта си, преди да продължите</strong>.','Update database' => 'Актуализиране на базата данни','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout не е съвместим с оформлението на касата на Divi Builder','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout се нуждае от класическата форма за плащане, базирана на кратките кодове на WooCommerce, за да работи. Когато използвате Divi Builder, за да персонализирате външния вид на страницата за плащане, класическите кратки кодове се заменят с персонализирани уиджети от Divi Builder за всяка част от страницата за плащане. Тези потребителски уиджети не са съвместими с Fluid Checkout.</p><p>Предайте страницата си за плащане, като замените уиджетите на Divi Builder с текстови уиджет, съдържащ краткия код <code>[woocommerce_checkout]</code>.</p>','Edit the checkout page' => 'Редактиране на страницата за плащане','Read the documentation.' => 'Прочетете документацията.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Функцията за многостъпково плащане на PRO трябва да бъде деактивирана, когато използвате Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Когато използвате Fluid Checkout, функцията за няколко стъпки от плъгина Germanized PRO става ненужна и може да доведе до <strong>критични грешки при обработката на нови поръчки</strong>. Моля, деактивирайте функцията за многостъпкова каса от Germanized PRO в настройките на плъгина.','Go to Germanized settings' => 'Отидете на германизирани настройки','Thanks for choosing Fluid Checkout!' => 'Благодарим ви, че избрахте Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Използвате плъгина от известно време насам. Как ви харесва досега? <br>Моля, дайте ни бърза оценка, оценяваме всяка обратна връзка и тя ни насърчава да продължаваме да подобряваме плъгина :)','Rate the plugin' => 'Оценете плъгина','I need help!' => 'Имам нужда от помощ!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Някои функции на WooCommerce Checkout Manager от Quadlayers може да не работят както се очаква, когато се използват с Fluid Checkout. Прочетете <a href="%s">нашата документация</a> за повече информация и алтернативни решения.','Read documentation' => 'Прочетете документацията','Don\'t show this again' => 'Не показвайте това отново','Fluid Checkout PRO' => 'Проверка на флуиди PRO','More design templates' => 'Още шаблони за дизайн','Optimized cart page' => 'Оптимизирана страница на количката','Optimized order received / thank you page' => 'Оптимизирана страница за получена поръчка / благодарност','Edit cart contents at checkout page' => 'Редактиране на съдържанието на количката в страницата за плащане','Account matching / user matching' => 'Съвпадение на акаунти / съвпадение на потребители','Trust symbols on the cart and thank you pages' => 'Символи за доверие в количката и страниците с благодарности','More positions for the coupon code on the checkout page' => 'Повече позиции за кода на купона на страницата за плащане','International phone numbers' => 'Международни телефонни номера','Gift messages and packing slips' => 'Послания за подаръци и опаковъчни листове','Local pickup and in-store collection' => 'Вземане на място и събиране в магазина','EU-VAT Assistant' => 'Асистент по ДДС за ЕС','I already have it – Hide this offer' => 'Вече я имам - Скрийте тази оферта','Activated' => 'Активиран','Address book' => 'Адресна книга','Select an image' => 'Изберете изображение','Cart layout' => 'Оформление на количката','Cart optimizations' => 'Оптимизации на количката','Enable cart page optimizations' => 'Активиране на оптимизации на страницата на количката','Header and footer template' => 'Шаблон за заглавие и колонтитул','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Контролира дали да се използват заглавието и долният колонтитул на страницата, които не отвличат вниманието, или да се запазят заглавието и долният колонтитул на активната в момента тема.','Distraction free header and footer' => 'Заглавие и колонтитул без разсейване','Theme\'s header and footer' => 'Заглавие и колонтитул на темата','Cart elements' => 'Елементи на количката','Make the order summary stay visible on the cart page while scrolling' => 'Направете така, че обобщението на поръчката да остава видимо на страницата на количката при превъртане','Coupon codes' => 'Кодове на купони','Hidden' => 'Скрит','Before the cart items section' => 'Преди секцията с елементи от количката','Inside the cart items section' => 'Вътре в раздела за елементи на количката','After the cart items section' => 'След раздела с елементи от количката','Before the shipping section' => 'Преди раздела за доставка','After the shipping section' => 'След раздела за доставка','Before the order summary' => 'Преди обобщението на поръчката','Inside the order summary' => 'Вътре в резюмето на поръчката','Before the order totals' => 'Преди общите суми на поръчките','After the order totals' => 'След сумирането на поръчките','After the order summary' => 'След обобщението на поръчката','Shipping' => 'Доставка','Select position where to display the shipping costs and calculator on the cart page.' => 'Изберете позицията, на която да се показват разходите за доставка и калкулаторът на страницата на количката.','Display as a cart section' => 'Показване като раздел на количката','Cross-sells' => 'Кръстосани продажби','Select position where to display the cross-sells section on the cart page.' => 'Изберете позиция, в която да се показва разделът за кръстосани продажби на страницата на количката.','Before the cart actions' => 'Преди действията с количката','After the cart actions' => 'След действията с количката','Layout of cross-sell items on the cart page.' => 'Оформление на елементите за кръстосана продажба на страницата на количката.','Optimized horizontal cross-sells layout' => 'Оптимизирано хоризонтално оформление на кръстосаните продажби','Theme\'s cross-sells layout' => 'Оформление на кръстосаните продажби на темата','Number of cross-sell items to display on the cart page' => 'Брой на елементите за кръстосана продажба, които да се показват на страницата на количката','Add widget areas to the cart page' => 'Добавяне на области с джаджи в страницата на количката','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Тези области с уиджети се използват за добавяне на символи за доверие и значки за доверие на страницата на количката.','Checkout' => 'Проверка на','Checkout layout' => 'Оформление на касата','Design template' => 'Шаблон за дизайн','Dark mode' => 'Тъмният режим','Enable dark mode' => 'Активиране на тъмен режим','Logo image' => 'Изображение на логото','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Изберете изображение, което да се показва в заглавието на страницата за плащане. Прилага се само при използване на заглавието и долния колонтитул, които не отвличат вниманието.','Header background color' => 'Цвят на фона на заглавието','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Изберете цвят на фона за заглавието на страницата за плащане. Прилага се само при използване на заглавието и долния колонтитул, които не отвличат вниманието.','HTML color value. ie: #f3f3f3' => 'Стойност на HTML цвят: #f3f3f3','Page background color' => 'Цвят на фона на страницата','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Изберете цвят на фона на страницата за плащане. Цветът се прилага към елемента <em>body</em>.','Footer background color' => 'Цвят на фона на колонтитула','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Изберете цвят на фона за долния колонтитул на страницата за плащане. Прилага се само при използване на заглавието и долния колонтитул, които не отвличат вниманието.','Progress bar' => 'Лентата за напредък','Display the checkout progress bar when using multi-step checkout layout' => 'Показване на лентата за напредъка на поръчката при използване на оформление за поръчка в няколко стъпки','Make the checkout progress bar stay visible while scrolling' => 'Направете така, че лентата за напредъка на поръчката да остава видима при превъртане','Express checkout' => 'Експресно изписване','Enable the express checkout section' => 'Активиране на раздела за експресно плащане','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Показва раздела за експресно плащане при поръчка, когато поддържаните шлюзове за плащане са активирали тази функция.','Display express checkout buttons in one line for larger screens' => 'Показвайте бутоните за експресно плащане на един ред за по-големи екрани','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Игнориране на допълнителни задължителни полета при плащане със съвместим шлюз за експресно плащане','Make the order summary stay visible while scrolling' => 'Направете така, че резюмето на поръчката да остава видимо при превъртане','Choose a background color for the order summary section.' => 'Изберете цвят на фона на раздела за обобщение на поръчките.','Highlight the order totals row in the order summary table' => 'Подчертайте реда с общите суми на поръчките в таблицата за обобщение на поръчките','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Най-полезно е, когато разделът за обобщение на поръчката няма подчертан фонов цвят. Може да се приложи и за страниците "Количка", "Получена поръчка" и "Преглед на поръчката", когато използвате Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Връзка за действие в обобщението на поръчката при плащане.','Edit cart link' => 'Редактиране на връзката на количката','Cart items count' => 'Брой на елементите в количката','Link to shop page' => 'Връзка към страницата на магазина','Cart items' => 'Елементи от количката','Hide cart items errors at the checkout page' => 'Скриване на грешките в количката в страницата за плащане','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Не показвайте съобщението за грешки в елементите на количката в горната част на страницата за плащане. При изпращане на формуляра за плащане, за да завършите покупката, тези съобщения за грешки винаги ще се показват.','Place order' => 'Поставяне на поръчка','Define the position to display "Place order" and terms checkbox section.' => 'Определете позицията за показване на раздела "Place order" (Поставяне на поръчка) и полето за отметка с условия.','Some options might not be compatible with some plugins and themes.' => 'Някои опции може да не са съвместими с някои плъгини и теми.','Below the payment section' => 'Под раздела за плащане','Below the order summary' => 'Под обобщението на поръчката','Both below the payment section and the order summary' => 'Както под раздела за плащане, така и под обобщението на поръчката','Add widget areas to the checkout page' => 'Добавяне на области с джаджи в страницата за плащане','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Тези области за уиджети се използват за добавяне на символи за доверие и значки за доверие на страницата за плащане.','Display the coupon codes section title' => 'Показване на заглавието на раздела с кодове на купони','Select position where to display the coupon codes section on the checkout page.' => 'Изберете позиция, в която да покажете раздела с кодове на купони на страницата за плащане.','Before the checkout steps' => 'Преди стъпките за проверка','As a substep before payment methods' => 'Като подстъпка преди методите на плащане','As a substep after payment methods' => 'Като подстъпка след методите на плащане','Default button style' => 'Стил на бутона по подразбиране','"Add" link button' => 'Бутон за връзка "Добавяне"','Checkout fields' => 'Полета за регистрация','Optional fields' => 'Незадължителни полета','Hide optional fields behind a link button' => 'Скриване на незадължителни полета зад бутон за връзка','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Препоръчително е тази опция да остане маркирана, за да се намали броят на отворените полета за въвеждане, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">прочетете изследването</a>.','Do not hide "Address line 2" fields behind a link button' => 'Не скривайте полетата "Адресен ред 2" зад бутон за връзка','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Препоръчва се само когато повечето клиенти действително се нуждаят от полето "Адресен ред 2" или когато получаването на правилния адрес за доставка е от решаващо значение (напр. при доставка на храни и други бързо развалящи се продукти).','Billing address' => 'Адрес за фактуриране','Select position where to display the billing address section on the checkout page.' => 'Изберете позиция, в която да се показва разделът с адреса за фактуриране на страницата за плащане.','As a step before shipping' => 'Като стъпка преди изпращането','As a sub-step before the shipping address section' => 'Като подетап преди раздела за адреса за доставка','As a sub-step after the shipping address section' => 'Като подстъпка след раздела за адреса за доставка','As a step after shipping' => 'Като стъпка след изпращането','As a sub-step before the payment section' => 'Като подстъпка преди раздела за плащане','Force billing and shipping addresses to the same (single section)' => 'Принудително задаване на едни и същи адреси за фактуриране и доставка (един раздел)','Checkbox for "Same as shipping/billing address" checked by default' => 'Полето за отметка "Същият като адреса за доставка/фактуриране" е маркирано по подразбиране','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Полето за отметка "Същото като адреса на изпращане" ще започне да се маркира по подразбиране, когато разделът с адреса на изпращане се показва за първи път. <br>Полето за отметка "Same as billing address" (Същото като адреса за фактуриране) ще започне да се маркира по подразбиране, когато разделът с адреса за фактуриране се покаже първи. <br> Препоръчително е да оставите тази опция отметната, тъй като за да намалите значително броя на отворените полета за въвеждане при поръчка, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">прочетете изследването</a>.','Highlight the billing address section in the checkout form' => 'Подчертайте раздела за адрес за фактуриране във формуляра за плащане','Shipping address' => 'Адрес за доставка','Highlight the shipping address section in the checkout form' => 'Подчертайте раздела за адрес за доставка във формуляра за поръчка','Shipping methods' => 'Методи за доставка','Choose in which position to display the shipping methods section.' => 'Изберете в коя позиция да се показва разделът с методите на доставка.','Before shipping address' => 'Преди адрес за доставка','After shipping address' => 'След адреса за доставка','Local pickup' => 'Вземане на място','Removes shipping address section when a local pickup shipping method is selected.' => 'Премахва раздела за адрес за доставка, когато е избран метод за доставка с местно вземане.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Заменя адреса за доставка с местоположението на мястото за получаване, когато е избран метод за доставка с местно получаване.','Choose which address to save as the shipping address for local pickup orders.' => 'Изберете кой адрес да бъде запазен като адрес за доставка за поръчките за местно вземане.','Save the selected pickup location' => 'Записване на избраното място за взимане','Save same as the billing address' => 'Запазете същия като адреса за фактуриране','Do not save any shipping address' => 'Не запазвайте адрес за доставка','Company name field for shipping address' => 'Поле за име на компанията за адреса за доставка','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Промяна на видимостта на полето за име на компанията в раздела за адрес на доставка във формуляра за поръчка.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Ако полето е зададено като "незадължително", което е състоянието на видимост по подразбиране, няма да бъдат приложени никакви промени, за да могат другите плъгини да приложат всички необходими промени.','Hidden (remove field)' => 'Скрито (премахване на полето)','Optional' => 'По избор','Required' => 'Изисква се','Add shipping phone field to the checkout form.' => 'Добавяне на поле за телефон за доставка към формуляра за поръчка.','Choose in which step to display the shipping phone field.' => 'Изберете в коя стъпка да се показва полето за телефон за доставка.','Contact step' => 'Стъпка за контакт','Billing phone' => 'Телефон за фактуриране','Add billing phone field to the checkout form.' => 'Добавяне на поле за телефон за фактуриране към формата за плащане.','Choose in which step to display the billing phone field.' => 'Изберете в коя стъпка да се показва полето за телефон за фактуриране.','Show country code beside the flag' => 'Показване на кода на страната до флага','Show an example of a valid phone number inside phone fields' => 'Показване на пример за валиден телефонен номер в полетата за телефон','Do not change placeholders' => 'Не променяйте заместителите','Show if not defined' => 'Покажи, ако не е дефинирано','Always show' => 'Винаги показвайте','Order notes' => 'Бележки за поръчка','Define the visibility of the additional order notes field.' => 'Определете видимостта на полето за допълнителни бележки към поръчката.','Gift options' => 'Опции за подарък','Allow customers to add a gift message and other gift related options to the order.' => 'Позволете на клиентите да добавят съобщение за подарък и други опции, свързани с подаръка, към поръчката.','Display the gift message as part of the order details table instead of a separate section' => 'Показване на съобщението за подарък като част от таблицата с подробна информация за поръчката вместо в отделен раздел','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Тази опция влияе на страницата за потвърждаване на поръчката (страница "Благодаря") и на данните за поръчката в страниците на акаунта, имейлите и опаковъчните листове.','Account matching' => 'Съвпадение на сметки','Enable the account matching feature' => 'Активиране на функцията за съвпадение на сметки','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Свържете поръчките на гостуващия клиент с неговия съществуващ акаунт, когато вече съществува акаунт с данните за контакт на клиента.','Display message when an account exists with the email address provided' => 'Показване на съобщение, когато съществува акаунт с предоставения имейл адрес','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Замества полетата за създаване на акаунт с известие и възможност за влизане. В някои контексти може да се препоръча тази опция да остане деактивирана, за да се защити поверителността на клиентите.','Dashboard' => 'Информационно табло','Integrations' => 'Интеграции','License keys' => 'Лицензионни ключове','Visit our website for more information about our plugins and add-ons.' => 'Посетете нашия уебсайт за повече информация относно нашите плъгини и добавки.','Order pay page' => 'Страница за плащане на поръчки','Order pay' => 'Плащане на поръчката','Enable order pay page optimizations' => 'Активиране на оптимизации на страницата за плащане на поръчки','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Променя оформлението на страницата за плащане на поръчки за съществуващи поръчки, които очакват плащане от клиента.','Add widget areas to the order pay page' => 'Добавяне на области с уиджети към страницата за плащане на поръчки','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Тези области за уиджети се използват за добавяне на символи за доверие и значки за доверие на страницата за плащане на поръчки.','Thank you page & order details layout' => 'Благодарствена страница и оформление на данните за поръчката','Order details optimizations' => 'Оптимизации на детайлите на поръчката','Enable thank you page and order details optimizations' => 'Активиране на оптимизациите на страницата с благодарности и подробностите за поръчката','Changes the layout of order details on the thank you page and account pages.' => 'Промяна на оформлението на данните за поръчката в страницата с благодарности и в страниците с акаунти.','Enable order details customizations on email notifications' => 'Активиране на персонализациите на подробностите за поръчката в имейл известията','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Показване на нови раздели и промяна на реда на разделите в имейл известията. Стиловете на подробностите за поръчката в имейл известията остават непроменени.','Thank you page' => 'Благодарствена страница','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Тези опции влияят на страницата с благодарности, известна още като страници за получена поръчка или потвърждение на поръчката.','Order details layout' => 'Оформление на детайлите на поръчката','Display the order details with wide layout on the thank you page' => 'Показване на данните за поръчката с широко оформление на страницата с благодарности','Add widget areas to the thank you page' => 'Добавяне на области с джаджи към страницата с благодарности','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Тези области за уиджети се използват за добавяне на символи за доверие и значки за доверие в страницата с благодарности.','Order actions' => 'Действия по поръчката','Choose in which position to display the order actions.' => 'Изберете в коя позиция да се показват действията по поръчката.','Inside the order overview' => 'Вътрешен преглед на поръчката','After the order overview' => 'След прегледа на поръчката','After order sections' => 'Секции след поръчка','Order status' => 'Статус на поръчката','Display the order status progress bar' => 'Показване на лентата за напредъка на състоянието на поръчката','Choose in which position to display the section.' => 'Изберете в коя позиция да се показва разделът.','After the order overview and payment instructions' => 'След прегледа на поръчката и инструкциите за плащане','Before the order items section' => 'Преди секцията с елементи на поръчката','Inside the order items section' => 'Вътре в раздела за елементи на поръчката','After the order items section' => 'След раздела за елементи на поръчката','On the sidebar' => 'В страничната лента','Order downloads' => 'Поръчка на изтегляния','Gift message' => 'Послание за подарък','Tools' => 'Инструменти','Troubleshooting' => 'Отстраняване на неизправности','Debug options' => 'Опции за отстраняване на грешки','Debug mode' => 'Режим за отстраняване на грешки','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Използването на режим за отстраняване на грешки се отразява на производителността на уебсайта. Използвайте тази опция само при отстраняване на неизправности.','Load unminified assets' => 'Зареждане на неминифицирани активи','Enhanced select fields' => 'Усъвършенствани полета за избор','Fix automatic zoom-in on form fields' => 'Поправяне на автоматичното увеличаване на полетата на формуляра','Set <code>font-size</code> inside form fields to 16px' => 'Задаване на <code>font-size</code> в полетата на формата на 16px','Fluid Checkout' => 'Проверка на флуидите','Settings' => 'Настройки','Support' => 'Подкрепа','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Подгответе се за PRO</a>, за да отключите повече опции.','(PRO)' => '(PRO)','(experimental)' => '(експериментално)','Please verify your phone number.' => 'Моля, проверете телефонния си номер.','The Bluehost Plugin' => 'Плъгинът на Bluehost','Custom fields' => 'Потребителски полета','Enable custom shipping email field' => 'Активиране на персонализирано поле за имейл за доставка','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Когато е разрешено, полето за имейл за доставка от плъгина на Bluehost ще бъде добавено към формуляра за поръчка.','Captcha Pro by BestWebSoft' => 'Captcha Pro от BestWebSoft','Captcha position' => 'Позиция на Captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Определете позицията за показване на раздела Captcha. Някои позиции може да не работят в зависимост от избрания тип captcha.','Selecting a pickup point is required before proceeding.' => 'Преди да продължите, е необходимо да изберете точка на взимане.','Pickup point' => 'Място на получаване','Pickup point not selected yet.' => 'Все още не е избрана точката на качване.','Pickup point:' => 'Място на получаване:','Mailchimp for WooCommerce' => 'Mailchimp за WooCommerce','Subscribe checkbox' => 'Поле за отметка за абонамент','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Отмяна на позицията на квадратчето за абонамент на страницата за поръчка и винаги го показвайте на стъпката за контакт','Before Shipping Address' => 'Преди адрес за доставка','(originally "%s")' => '(първоначално "%s")','After Shipping Address' => 'След адрес за доставка','Selecting a collection point is required when shipping with FermoPoint.' => 'При транспортиране с FermoPoint е необходимо да се избере точка за събиране.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Ако е маркирано, информира потребителите за печатни грешки в имейлите. (Тази функция е деактивирана, тъй като Fluid Checkout предлага тази функция. Промените в тази опция няма да влязат в сила)','Enable Mail Check: (disabled feature)' => 'Активиране на проверката на пощата: (деактивирана функция)','Carrier:' => 'Преносител:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce имейл маркетинг','Sign up checkbox position' => 'Позиция на квадратчето за регистрация','Move the sign up checkbox to the contact step' => 'Преместване на квадратчето за регистрация в стъпката за контакт','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Когато е разрешено, квадратчето за отметка ще бъде преместено в стъпката за контакт независимо от мястото на показване, определено в настройките на плъгина Sendinblue.','Theme Betheme' => 'Тема Betheme','Checkout progress' => 'Напредък на поръчката','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Извеждане на секцията със стъпките за плащане от Betheme на страниците за плащане, количката и получената поръчка.','Theme Fennik' => 'Тема Fennik','Breadcrumbs' => 'Хлебни трохи','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Извеждане на секцията с трохите от темата Fennik при използване на заглавието и долния колонтитул на Fluid Checkout.','Theme Go' => 'Тема Go','My account layout' => 'Оформление на профила ми','Enable wide layout on "My account" page.' => 'Активиране на широко оформление на страницата "Моят акаунт".','Theme Impreza' => 'Тема Impreza','Header' => 'Заглавие','Spacing for site header at the checkout page (in pixels)' => 'Разстояние между заглавието на сайта в страницата за плащане (в пиксели)','Only applicable when using the Impreza theme header at the checkout page.' => 'Прилага се само при използване на заглавието на темата Impreza в страницата за плащане.','Theme Kapee' => 'Тема Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Изведете раздела със стъпките за плащане от темата Kapee на страниците за плащане, количката и получената поръчка.','Theme Porto' => 'Тема Порто','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Изведете раздела за стъпките за плащане от темата Porto на страниците за плащане, количката и получената поръчка.','Theme Pressmart' => 'Тема Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Изведете раздела за стъпките за плащане от темата Pressmart на страниците за плащане, количката и получената поръчка.','Theme The Gem' => 'Темата на скъпоценния камък','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Извеждане на секцията със стъпките за плащане от темата Gem при използване на заглавието и долния колонтитул на Fluid Checkout.','Theme Woodmart' => 'Тема Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Извеждане на секцията със стъпките на касата от темата Woodmart при използване на заглавието и долния колонтитул на Fluid Checkout.','Checkout options' => 'Опции за поръчка','Disable the theme checkout options' => 'Деактивиране на опциите на темата за плащане','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Добавените от темата опции за показване на изображение на продукта, поле за количество, бутон за премахване и връзка към страницата на продукта са деактивирани по подразбиране.','Theme Atomion' => 'Тема Atomion','Order progress' => 'Напредък на поръчката','Display order progress from the theme' => 'Показване на напредъка на поръчката от темата','Display the form field labels visible on the page' => 'Показване на етикетите на полетата на формуляра, видими на страницата','It is recommended to keep this option enabled for a better user experience.' => 'Препоръчително е тази опция да бъде активирана за по-добро потребителско изживяване.','Theme ZK Nito' => 'Тема ZK Nito','Add extra fields to the checkout form' => 'Добавяне на допълнителни полета във формата за плащане','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Добавя допълнително поле за имейл за доставка и телефон за доставка в раздела за адрес за доставка.','Go to the home page' => 'Отидете на началната страница','Skip to content' => 'Преминаване към съдържанието','Create an account' => 'Създаване на акаунт','Log in to your account' => 'Влезте в профила си','Already have an account?' => 'Вече имате акаунт?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Влезли сте като %1$s. <a href="%2$s">Излизане</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Общата дължима сума на вашата поръчка е %s. Не е необходимо допълнително плащане.','Close and continue with checkout' => 'Затваряне и продължаване на поръчката','Continue' => 'Продължи','Parcel terminal' => 'Терминал за пратки','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Тази джаджа е заменена от Fluid Checkout. </p><p>При използване на Fluid Checkout страницата за поръчка трябва да използва оригиналния шорткode на WooCommerce <code>[woocommerce_checkout]</code>, за да работи правилно.</p><p>За повече информация посетете документацията на Fluid Checkout.</p>','Theme The7' => 'Темата The7','Additional header sections' => 'Допълнителни раздели на заглавието','Output additional header sections if enabled in the theme settings.' => 'Извеждане на допълнителни секции в заглавието, ако това е разрешено в настройките на темата.','More information' => 'Повече информация','Pick a Locker' => 'Изберете шкафче','Page template' => 'Шаблон на страницата','Use `Order confirmation` page template for block-based themes' => 'Използване на шаблона на страницата `Потвърждаване на поръчката` за блок-базирани теми','Only applies when using a block-based theme.' => 'Прилага се само при използване на тема, базирана на блокове.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'Формуляр за плащане','Apply styles to the Stripe payment form fields' => 'Прилагане на стилове към полетата на формата за плащане на Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Когато е разрешено, Fluid Checkout ще прилага стилове, оптимизирани за съвместимост с плъгина. Може да искате да деактивирате тази опция, ако използвате персонализирани стилове за полетата на формата за плащане на Stripe.','Theme Nyture' => 'Тема Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Извеждане на секцията със стъпките на касата от темата Nyture при използване на Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Позволява на клиентите да извършват плащания за поръчки, които са създадени ръчно от администратора на магазина или не са завършени по време на поръчката.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Плъгинът WooCommerce Checkout Manager от Quadlayers не е съвместим с Fluid Checkout','Company name field for billing address' => 'Поле за име на фирма за адреса за фактуриране','Change visibility for the company name field for the billing address section on the checkout form.' => 'Промяна на видимостта на полето за име на компанията в раздела за адрес за фактуриране във формуляра за плащане.','Theme Bookshelf' => 'Рафт за книги по темата','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Извеждане на секцията със стъпките за плащане от темата Bookshelf при използване на Fluid Checkout.','Account password' => 'Парола на акаунта','An account will be created with the information provided at checkout when completing the order.' => 'Ще бъде създаден акаунт с информацията, предоставена на касата при завършване на поръчката.','Choose the style of the progress bar.' => 'Изберете стила на лентата за напредък.','Bars' => 'Барове','Theme Ireca' => 'Тема Ireca','WooCommerce page layout' => 'Оформление на страницата на WooCommerce','Force wide layout on WooCommerce pages' => 'Принудително широко оформление на страниците на WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Това гарантира, че секцията със съдържание не е твърде тясна на страниците на WooCommerce, включително страниците за поръчка, количка, получена поръчка, плащане на поръчка и акаунт.','WooCommerce Smart Coupons' => 'WooCommerce Smart Coupons','Position on checkout page' => 'Позиция на страницата за поръчка','Choose where to display the available coupons section on the checkout page.' => 'Изберете къде да се покаже разделът с наличните купони на страницата за плащане.','Before the progress bar' => 'Преди лентата за напредък','After the progress bar' => 'След лентата за напредък','Before coupon codes section' => 'Преди раздел кодове на купони','Format phone numbers according to the rules for each country.' => 'Форматирайте телефонните номера в съответствие с правилата за всяка страна.','Use precise phone number validation' => 'Използвайте точно валидиране на телефонния номер','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Това е експериментална функция и е възможно да не работи според очакванията при всички настройки. Използвайте я с повишено внимание.','Phone number validation types used when precise validation is enabled.' => 'Типове валидиране на телефонни номера, използвани, когато е разрешено точното валидиране.','Mobile' => 'Мобилен','Fixed line' => 'Фиксирана линия','Toll free' => 'Безплатно','Contact' => 'Свържете се с','Multi step' => 'Няколко стъпки','2 columns' => '2 колони','1 column' => '1 колона','Before checkout steps' => 'Стъпки преди поръчката','Or' => 'Или','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Когато използвате оформлението на касата <em>"1 колона"</em>, тази опция винаги е настроена на <em>"Преди стъпките на касата"</em> и се отнася и за изгледа за настолни компютри.','Position for the extra order summary section on mobile.' => 'Позиция за допълнителния раздел за обобщение на поръчките в мобилните устройства.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Опцията <em>"В заглавието на сайта"</em> се прилага само при използване на заглавието без отвличане на вниманието.','On the site header (requires distraction-free header)' => 'В заглавието на сайта (изисква заглавие, което не отвлича вниманието)','Initial state for the expansible order summary section on mobile.' => 'Първоначално състояние на разширяемия раздел за обобщение на поръчките за мобилни устройства.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Препоръчваме да го зададете като <em>разширен</em> за следните държави поради регулаторни изисквания: <strong>Германия</strong>, <strong>Австрия</strong>, <strong>Швейцария</strong>, <strong>Нидерландия</strong>, <strong>Полша</strong>, <strong>Белгия</strong> и <strong>Франция</strong>.','Collapsed' => 'Сринат','Expanded' => 'Разширен','Do not show' => 'Не показвайте','yes' => 'да','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Полето за телефонен номер за доставка може да бъде маркирано като „задължително“, ако разделът с адреса за фактуриране се показва след раздела с адреса за доставка, а полето за телефонен номер за фактуриране е маркирано като „задължително“. Това е необходимо, за да се гарантира, че адресът за доставка може да бъде копиран в адреса за фактуриране, когато тази опция е отбелязана; в противен случай клиентът може да не успее да попълни формуляра за плащане.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Полето за телефон за фактуриране може да бъде маркирано като „задължително“, ако разделът с адреса за фактуриране се показва преди раздела с адреса за доставка, а полето за телефон за доставка е маркирано като „задължително“. Това е необходимо, за да се гарантира, че адресът за доставка може да бъде копиран в адреса за фактуриране, когато тази опция е отбелязана; в противен случай клиентът може да не успее да попълни формуляра за плащане.','Settings profiles' => 'Профили за настройки','Settings profile' => 'Профил на настройките','You do not have permission to perform this action.' => 'Нямате разрешение да извършите това действие.','You do not have permission to activate plugins.' => 'Нямате разрешение да активирате плъгини.','Missing plugin.' => 'Липсващ плъгин.','Plugin activated.' => 'Плъгинът е активиран.','The following changes will be applied:' => 'Ще бъдат приложени следните промени:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'От версия 5.0 на Fluid Checkout нататък настройките се запазват по различен начин. Старите опции все още се съхраняват в базата данни, за да се даде възможност за преминаване към по-стари версии, ако се наложи.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Вашият магазин работи от около 2 седмици с новите настройки, което ви даде възможност да изчистите старите опции, съхранени в базата данни. Моля, имайте предвид, че след почистването, ако се наложи да се върнете към предишни версии на приставката, тя ще използва стойностите по подразбиране за всички настройки.','Fluid Checkout settings cleanup' => 'Почистване на настройките на „Fluid Checkout“','Delete leftover options' => 'Изтриване на останалите опции','Help us improve Fluid Checkout' => 'Помогнете ни да подобрим „Fluid Checkout“','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Споделяйте анонимни отчети за средата на сайта чрез Fluid Checkout, за да получите по-бърза поддръжка и да ни помогнете да подобрим съвместимостта и да оценим въздействието. Не се включват данни за клиенти, потребители или чувствителна информация. Можете да изберете какво да се споделя по всяко време от настройките в раздела „Инструменти“.','Enable site environment reports' => 'Активиране на отчетите за средата на сайта','Review settings' => 'Преглед на настройките','This preview has expired. Reload the admin page to start a new preview.' => 'Срокът на този преглед е изтекъл. Опреснете страницата за администратори, за да стартирате нов преглед.','Preview expired' => 'Срокът на валидност на предварителния преглед изтече','Orders cannot be placed in the preview.' => 'В режима на предварителен преглед не могат да се правят поръчки.','Logging in is not available in the preview.' => 'Въвеждането на данни за вход не е достъпно в предварителния преглед.','Accounts cannot be created in the preview.' => 'В режима на предварителен преглед не могат да се създават акаунти.','Requests to other sites are blocked in the preview.' => 'Заявките към други сайтове се блокират в режима на предварителен преглед.','Processing…' => 'Обработва се…','Something went wrong. Please try again.' => 'Възникна проблем. Моля, опитайте отново.','Activate plugin' => 'Активиране на плъгина','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO – Пълен пакет за плащане','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Всички функции на PRO + всички добавки – на една цена. Дизайнерски шаблони, оптимизирани страници за кошницата и потвърждение на поръчката, синхронизиране на профили и много други.','Optimized order pay page' => 'Оптимизирана страница за плащане на поръчка','Express checkout buttons from supported payment methods' => 'Бутони за експресно плащане от поддържаните начини на плащане','Delayed account creation' => 'Забавено създаване на профил','Address autocomplete with Google Maps APIs' => 'Автоматично попълване на адреси с API-та на Google Maps','Multiple saved addresses with the address book' => 'Множество запазени адреси в адресната книга','EU-VAT assistant' => 'Помощник за ДДС в ЕС','Hide this section' => 'Скрий тази секция','Learn more' => 'Научете повече','Get early access' => 'Получете ранен достъп','Activate add-on' => 'Активиране на добавката','Get more out of your checkout journey' => 'Извлечете максимална полза от процеса на плащане','Test API key' => 'Тестване на API ключ','Guided setup' => 'Настройка с помощта на указания','Options' => 'Опции','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Настройте оформлението и дизайна на <a href="%s">опциите за плащане</a>.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Активирайте опцията за плащане като гост и/или прегледайте <a href="%s">настройките на клиентските профили</a>.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Активирайте оптимизираните страници <a href="%1$s">кошница</a>, <a href="%2$s">благодарност</a> и <a href="%3$s">плащане на поръчката</a>.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Активирайте <a href="%s">автоматичното попълване на адреси</a> от Google Maps.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Активирайте възможността за запаметяване на множество адреси чрез <a href="%s">адресна книга</a>.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Проверете дали има някакви <a href="%s">възможности за интеграция</a> за темата или другите плъгини, които сте инсталирали.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Получете по-бърза поддръжка и ни помогнете да подобрим съвместимостта и да измерим въздействието. <a href="%s">Активирайте проследяването на използването</a> от настройките на инструмента.','Missing settings tab.' => 'Липсва раздел „Настройки“.','Getting started' => 'Първи стъпки','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Страхотно! Страницата ви за плащане вече работи с Fluid Checkout.</strong> Ето няколко стъпки, с които да започнете:','Completed' => 'Завършено','Preview report data' => 'Преглед на данните от отчета','Send now' => 'Изпрати сега','Auto-detect' => 'Автоматично разпознаване','Afrikaans' => 'африкаанс','Albanian' => 'албански','Amharic' => 'амхарски','Arabic' => 'арабски','Armenian' => 'Арменски','Azerbaijani' => 'азербайджански','Basque' => 'баски','Belarusian' => 'беларуски','Bengali' => 'бенгалски','Bosnian' => 'босненски','Bulgarian' => 'Български','Burmese' => 'бирмански','Catalan' => 'каталонски','Chinese' => 'Китайски','Chinese (Simplified)' => 'Китайски (опростен)','Chinese (Hong Kong)' => 'Китайски (Хонконг)','Chinese (Traditional)' => 'Китайски (традиционен)','Croatian' => 'Хърватски','Czech' => 'чешки','Danish' => 'датски','Dutch' => 'холандски','English' => 'английски','English (Australian)' => 'Английски (австралийски)','English (Great Britain)' => 'Английски (Великобритания)','Estonian' => 'естонски','Farsi' => 'Фарси','Finnish' => 'фински','Filipino' => 'филипински','French' => 'френски','French (Canadian)' => 'Френски (канадски)','Galician' => 'галисийски','Georgian' => 'грузински','German' => 'Немски','Greek' => 'гръцки','Gujarati' => 'гуджарати','Hebrew' => 'Иврит','Hindi' => 'Хинди','Hungarian' => 'унгарски','Icelandic' => 'исландски','Indonesian' => 'индонезийски','Italian' => 'италиански','Japanese' => 'Японски','Kannada' => 'Каннада','Kazakh' => 'казахски','Khmer' => 'кхмерски','Korean' => 'Корейски','Kyrgyz' => 'Киргиз','Lao' => 'Лао','Latvian' => 'латвийски','Lithuanian' => 'литовски','Macedonian' => 'македонски','Malay' => 'малайски','Malayalam' => 'малаялам','Marathi' => 'маратхи','Mongolian' => 'монголски','Nepali' => 'непалски','Norwegian' => 'Норвежки','Polish' => 'полски','Portuguese' => 'португалски','Portuguese (Brazil)' => 'Португалски (Бразилия)','Portuguese (Portugal)' => 'Португалски (Португалия)','Punjabi' => 'Панджаби','Romanian' => 'румънски','Russian' => 'руски','Serbian' => 'сръбски','Sinhalese' => 'синхалски','Slovak' => 'Словашки','Slovenian' => 'словенски','Spanish' => 'Испански','Spanish (Latin America)' => 'Испански (Латинска Америка)','Swahili' => 'суахили','Swedish' => 'Шведски','Tamil' => 'Тамилски','Telugu' => 'Телугу','Thai' => 'Тайски','Turkish' => 'Турски','Ukrainian' => 'украински','Urdu' => 'Урду','Vietnamese' => 'виетнамски','Zulu' => 'Зулу','Google address autocomplete' => 'Автоматично попълване на адреси от Google','Google Places API version' => 'Версия на API-то на Google Places','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Изберете коя версия на API-то на Google Places да използвате. Препоръчваме ви да преминете към новото API на Places възможно най-скоро.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Препоръчваме да използвате „Places API (New)“, тъй като от 1 март 2025 г. Google ще прехвърли версията „Places API (Legacy)“ в статус „Legacy“, което означава, че вече няма да можете да активирате тази услуга за нови API ключове и че тази версия на API-то в крайна сметка ще престане да бъде достъпна. Съществуващите акаунти, които вече използват Legacy API, ще продължат да работят без прекъсвания.','(Recommended)' => '(Препоръчително)','Google API key' => 'Ключ за API на Google','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Поставете ключа си за Google API и използвайте бутона за тестване, за да проверите дали работи за този уебсайт. Уверете се, че ключът е валиден и разрешен за вашия домейн, в противен случай полето за адрес може да бъде блокирано, което ще попречи на клиентите да завършат поръчките си.','Enable Google address autocomplete' => 'Активиране на функцията за автоматично попълване на адреси от Google','Enable address autocompletion using the Google Maps APIs.' => 'Активирайте автоматичното попълване на адреси чрез API-та на Google Maps.','Google API language' => 'Език на API-то на Google','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Този език ще се използва за показване на предложенията за адреси от API-то на Google Places, като адресите също ще се попълват автоматично на този език.','Result types' => 'Видове резултати','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Оставете полето празно, за да се приемат всички видове резултати, което обикновено води до по-добро съвпадение. <a href="%s" target="_blank">Вижте документацията за повече подробности</a>. <br>Изберете до 5 вида резултати от търсене на адреси, които да се показват в полетата за автодопълване на адреси. <br>Посетете документацията на Google Maps, за да научите повече за <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">поддържаните типове</a>.','Result types (Legacy API)' => 'Типове резултати (старо API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Какъв тип резултати от търсене по адрес да се връщат при използване на Places API (Legacy). <br>Посетете документацията на Legacy Google Places API, за да научите повече за <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">поддържаните типове</a>.','Company fields' => 'Полетата на компанията','Enable autocomplete for the company name if available' => 'Активирайте функцията за автоматично попълване на името на фирмата, ако е налична','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Активирайте автоматичното попълване на полето „Компания“ с информацията за името на компанията, когато тя се връща от API-та на Google Maps.','Business search' => 'Търсене на фирми','Enable search for businesses in the company field' => 'Активиране на търсенето на фирми в полето „Компания“','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Активирайте предложенията за адреси, свързани с дадена фирма, при въвеждане в полето „Фирма“, след което активирайте автоматичното попълване на всички полета за адрес, когато се избере фирма от предложените варианти.','Company result types' => 'Видове финансови резултати на дружествата','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Изберете до 5 типа резултати от търсене на адреси, които да се показват при автодопълване на фирмените полета. <br>Препоръчителната стойност е <code>обект</code>, която обхваща повечето видове фирми. <br>Оставете полето празно, за да се приемат всички видове резултати, включително и такива, които не са свързани с фирми. <br>Посетете документацията на Google Maps, за да научите повече за <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">поддържаните типове</a>.','Google logo' => 'Логото на Google','Show text and logo "Powered by Google"' => 'Показване на текста и логото „Powered by Google“','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Когато тази опция е отбелязана, текстът и логото „Powered by Google“ ще се показват в долната част на полето с предложения за автоматично попълване на адреса.','Brasil API address autocomplete' => 'Автоматично попълване на адреси чрез API за Бразилия','Brasil API' => 'API за Бразилия','Enable Brasil API address autocomplete for CEP fields' => 'Активиране на автоматичното попълване на адреси чрез API на „Enable Brasil“ за полетата за CEP','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Използвайте API-то на Brasil, за да извличате и попълвате автоматично адреси чрез полето „CEP/Пощенски код“. Приложимо само за адреси в Бразилия.','API version' => 'Версия на API','Choose which version of the Brasil API CEP method to use.' => 'Изберете коя версия на метода „CEP“ на API-то на Brasil да използвате.','Address book migration' => 'Прехвърляне на адресната книга','WooCommerce addresses' => 'Адреси на WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Копирайте съществуващите адреси за доставка и фактуриране от WooCommerce в адресната книга на клиентите.','Enable the address book feature' => 'Активиране на функцията „Адресна книга“','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Дайте възможност на клиентите да запаметяват няколко адреса и да определят адреса по подразбиране, който да се използва за доставка и фактуриране.','Address labels' => 'Етикети с адреси','Allow customers to add a custom label for each address' => 'Дайте възможност на клиентите да добавят персонализиран етикет за всеки адрес','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Етикетите с адреси улесняват клиентите да разграничават запазените си адреси (например: „Къщата на мама“). Етикетите с адреси са лични за клиентите и няма да се показват или отпечатват на страницата с подробностите за поръчката или във фактурите.','Display layout' => 'Оформление на екрана','Choose how saved addresses are displayed at checkout and on the cart.' => 'Изберете как да се показват запазените адреси при плащане и в кошницата.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Прилага се при плащане и в кошницата. Запазените адреси на страницата на профила винаги се показват в формат „карти“.','Address cards' => 'Визитни картички','Address list' => 'Списък с адреси','Dropdown field' => 'Поле с падащо меню','Address search' => 'Търсене по адрес','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Показване на филтъра за търсене на адреси в потребителския интерфейс, когато клиентът разполага с поне този брой запазени адреси.','Not used when display layout is set to dropdown field.' => 'Не се използва, когато оформлението на екрана е зададено като падащо меню.','Addresses' => 'Адреси','Enable cart page optimizations to see more options' => 'Активирайте оптимизациите на страницата с количката, за да видите повече опции','Sticky order summary' => 'Закрепено обобщение на поръчката','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Изберете мястото, където да се показва разделът с кодовете за отстъпка на страницата с количката. Това важи само когато е активирана AJAX количката и ако използването на кодове за отстъпка е разрешено в настройките на WooCommerce.','Layout of cross-sell' => 'Схема на кръстосаните продажби','Cross-sells displayed' => 'Показани са допълнителни предложения','Items' => 'Артикули','Cart page optimization' => 'Оптимизация на страницата с количката','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Оформете кошницата си по същия ясен и насочен към реализацията начин, както и страницата за плащане.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Съгласувайте оформлението на количката със страницата за плащане, за да осигурите последователен процес на покупка.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Количката да се актуализира постоянно във фонов режим, без презареждане на цялата страница при промяна на количествата.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Поставете кодовете за отстъпка, информацията за доставката и предложенията за допълнителни продукти точно там, където те водят до най-висока конверсия.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Оставете обобщението на поръчката видимо при превъртане и добавете символи, вдъхващи доверие, там, където купувачите се нуждаят от увереност.','Columns' => 'Колони','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Общи стилове за етапите на плащане, обобщението на поръчката и други раздели. Прилага се към другите страници за плащане, кошница, благодарност (получена поръчка) и преглед на поръчката.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Когато се използва оформлението <em>„1 колона“</em> с шаблона <em>„Split“</em>, дясната колона се показва само ако зоната за джаджи в страничната лента на страницата е активна („Странична лента при плащане“, „Странична лента на количката“ или „Странична лента за получени поръчки“). В противен случай страницата остава едноколона с стиловете на „Split“.','Split column background' => 'Разделен фон на колоната','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Изберете цвят на фона за втората колона в дизайна „Split“. Оставете полето празно, за да се използва цветът на фона на обобщението на поръчката.','Page templates' => 'Шаблони за страници','Checkout template' => 'Шаблон за плащане','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Препоръчва се за намаляване на отвличащите фактори при плащането. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Прочетете проучването за изоставянето на количките</a>.','Sticky progress bar' => 'Фиксирана лента за напредък','Progress bar style' => 'Стил на индикатора за напредък','Order totals' => 'Обща стойност на поръчката','Background color' => 'Цвят на фона','Action link' => 'Връзка за действие','Mobile order summary' => 'Обобщение на мобилната поръчка','Mobile initial state' => 'Начално състояние на мобилното устройство','Enable editing cart items at checkout' => 'Активиране на редактирането на артикулите в количката при плащане','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Дайте възможност на клиентите да променят количествата на продуктите или да премахват артикули директно на страницата за плащане.','Cart item errors' => 'Грешки при добавяне на артикули в количката','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Приложимо е само когато кодът на купона се показва като отделна секция на страниците за плащане или в кошницата, както и ако използването на кодове за купони е активирано в настройките на WooCommerce.','Coupon codes position' => 'Позиция на кодовете за отстъпка','Apply coupon button' => 'Бутон „Приложи купон“','Select style of the "apply coupon" button.' => 'Изберете стил на бутона „Приложи купон“.','Address line 2' => 'Втора реда на адреса','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Тази настройка се прилага едновременно за разделите „Плащане“ и „Вземане от магазин“. В раздела „Вземане от магазин“ тя определя също така дали изборът „Доставка/Вземане“ да се показва в раздела с начините на доставка (преди адреса) или като отделен раздел (след него).','Customer accounts' => 'Клиентски профили','Guest checkout' => 'Плащане като гост','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Опции за плащане като гост, влизане в профил и създаване на профил от страницата с настройки „Профили“ в WooCommerce. Те се управляват тук за ваше удобство, като по този начин можете да използвате различни настройки за всеки профил.','Allow customers to checkout without an account' => 'Дайте възможност на клиентите да извършват поръчки без да имат профил','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Препоръчително</strong>, за да не се изисква от клиентите да създават профил или да влизат в системата по време на плащането, което може да доведе до понижаване на процента на реализация.','When disabled, customers must log in or create an account to complete the purchase.' => 'Когато тази опция е деактивирана, клиентите трябва да влязат в профила си или да създадат профил, за да завършат покупката.','Login at checkout' => 'Влезте в профила си при плащане','Enable log-in during checkout' => 'Активиране на влизане в системата по време на плащане','Show a link for returning customers to log in from the checkout page.' => 'Покажете линк, чрез който редовните клиенти да могат да влязат в профила си от страницата за плащане.','Account creation' => 'Създаване на профил','Allow customers to create an account during checkout' => 'Дайте възможност на клиентите да създадат профил по време на плащането','Customers can create an account before placing their order.' => 'Клиентите могат да си създадат профил, преди да направят поръчката си.','Allow customers to create an account from the My account page' => 'Дайте възможност на клиентите да създадат профил от страницата „Моят профил“','Customers can register a new account from the My account page.' => 'Клиентите могат да регистрират нов акаунт от страницата „Моят акаунт“.','Username' => 'Потребителско име','Generate from customer\'s name' => 'Генериране въз основа на името на клиента','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Препоръчително</strong>, за да не се налага на клиентите да избират потребителско име при финализиране на поръчката, което може да доведе до понижаване на процента на конверсия.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Потребителското име се генерира въз основа на името на клиента или въз основа на имейл адреса, когато не може да се използва името.','Password' => 'Парола','Send password setup link' => 'Изпрати линк за създаване на парола','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Препоръчително</strong>, за да не се налага на клиентите да задават парола по време на плащането, което може да доведе до понижаване на процента на реализация.','Customers receive an email to create their password securely.' => 'Клиентите получават имейл, чрез който могат да създадат своята парола по сигурен начин.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Позволете на регистрираните клиенти да завършат поръчката, без да се вписват, и свържете поръчката с вече съществуващия им акаунт, когато данните за контакт съвпадат.','Existing account message' => 'Съобщение за съществуващ акаунт','Let customers create an account after placing their order, from the thank you page.' => 'Позволете на клиентите да създадат профил след като направят поръчката си, директно от страницата с благодарност.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Опциите в този раздел са достъпни, когато са активирани функциите за плащане като гост и съпоставяне на профили. Активирайте и двете функции по-горе, за да настроите отложено създаване на профил.','Enable delayed account creation' => 'Активиране на забавено създаване на профил','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Активирайте забавеното създаване на профил, когато са активирани както плащането като гост, така и съпоставянето на профили.','Section position' => 'Позиция в секцията','Before customer details section' => 'Преди раздела с данните за клиента','After customer details section' => 'След раздела с данните за клиента','Account creation benefits' => 'Предимства при създаването на профил','Leaving the field empty will display the default text.' => 'Ако оставите полето празно, ще се покаже текстът по подразбиране.','Inline buttons' => 'Вградени бутони','Required fields' => 'Задължителни полета','Enable gift message fields at checkout' => 'Активиране на полетата за послания към подаръка при плащане','Expanded gift message' => 'Разширено послание към подаръка','Display gift message field always expanded' => 'Полето за подаръчно съобщение да се показва винаги разгънато','Gift message in order details' => 'Послание към подаръка в подробностите за поръчката','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'В момента в този раздел няма налични интеграции. Опциите, свързани с всеки плъгин и тема, ще се появят тук едва след като съответният плъгин или тема бъде активиран/а.','Phone fields' => 'Полета за телефон','Field visibility' => 'Видимост на полето','Field position' => 'Позиция на терена','Phone country code & validation' => 'Телефонен код на държавата и проверка на валидността','Country' => 'Страна','Enable country on phone fields' => 'Активиране на полетата за държава в телефона','Filter countries for shipping or billing' => 'Филтриране на държави за доставка или фактуриране','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Ограничете избора на държава във всяко поле за телефонен номер до държавите, които са разрешени за доставка или фактуриране във вашия магазин.','Validation' => 'Валидиране','Enable simple validation based on country rules' => 'Активиране на опростена проверка въз основа на правилата за отделните държави','Checks that the phone number is valid for the selected country, including country code and length.' => 'Проверява дали телефонният номер е валиден за избраната страна, включително кодът на страната и броят на цифрите.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'По-строга проверка дали номерът е валиден мобилен, стационарен или друг допустим тип за избраната страна. Възможно е някои валидни номера да бъдат отхвърлени.','Validation types' => 'Видове валидиране','Placeholders' => 'Заместващи символи','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'В момента няма лицензионни ключове за управление. Лицензионните ключове ще се появят тук, когато е активен лицензиран плъгин или добавка за Fluid Checkout.','Default delivery type' => 'Стандартен начин на доставка','Choose which delivery type will be selected by default.' => 'Изберете кой тип доставка да бъде избран по подразбиране.','Shipping zone fields' => 'Полета за зони за доставка','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Изберете кои полета да се показват във филтъра за зоните за доставка при локално вземане. Оставете полето празно, за да се покажат всички налични опции.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Тези полета ще се показват като филтър за начините на доставка с локално получаване. Някои полета може все пак да се появяват при финализиране на поръчката, дори ако не са избрани тук, ако съвместимите плъгини изискват тяхното попълване, за да функционират правилно.','Order shipping address' => 'Адрес за доставка на поръчката','Order pay page optimization' => 'Оптимизация на страницата за плащане на поръчки','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Осигурете на неплатените поръчки същия ясен и насочен към реализацията дизайн, какъвто има страницата за плащане.','Optimize the layout of the order pay page for orders pending payment.' => 'Оптимизирайте оформлението на страницата за плащане на поръчките, които очакват плащане.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Съгласувайте процеса на плащане с вашата система за финализиране на поръчката, за да осигурите последователен процес на покупка.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Добавете символи и значки, които вдъхват доверие, там, където купувачите се нуждаят от увереност, преди да извършат плащане.','Thank you page optimization' => 'Оптимизация на страницата с благодарности','Make the thank you page and order details clearer for customers after they buy.' => 'Направете страницата с благодарност и подробностите за поръчката по-ясни за клиентите след покупката.','Optimize the thank you page and account order details with a clearer layout.' => 'Оптимизирайте страницата с благодарност и подробностите за поръчката в профила чрез по-ясно оформление.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Показвайте статуса на поръчката, действията, изтеглянията и бележките там, където е уместно.','Customize order details sections on email notifications.' => 'Персонализирайте разделите с подробности за поръчката в имейл уведомленията.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Добавете символи и значки, които вдъхват доверие, там, където купувачите се нуждаят от увереност след покупката.','Email notifications' => 'Известия по имейл','Enable thank you page and order details optimizations to see more options' => 'Активирайте оптимизациите на страницата с благодарност и на подробностите за поръчката, за да видите повече опции','Use wide layout on thank you page' => 'Използвайте широко оформление на страницата с благодарности','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Тези настройки засягат страницата с благодарност, прегледа на подробностите за поръчката на страниците на профила и в имейл уведомленията.','Save settings' => 'Запази настройките','Docs' => 'Документи','Cart' => 'Кошница','Thank you' => 'Благодаря','Address autocomplete' => 'Автоматично попълване на адреса','Trust badges' => 'Значки за доверие','You do not have permission to save these settings.' => 'Нямате право да запазите тези настройки.','Invalid save request.' => 'Невалидно искане за запазване.','Your settings have been saved.' => 'Настройките ви бяха запазени.','Saving...' => 'Записва се...','Settings could not be saved. Please try again.' => 'Настройките не можаха да бъдат запазени. Моля, опитайте отново.','Dismiss notice' => 'Затвори съобщението','Open settings menu' => 'Отвори менюто с настройките','Close settings menu' => 'Затвори менюто с настройките','Preview' => 'Предварителен преглед','Expand preview' => 'Разгърни предварителния преглед','Collapse preview' => 'Скрий предварителен преглед','Show header and footer' => 'Показване на заглавие и подзаглавие','Hide header and footer' => 'Скриване на горния и долния колонтитул','Page preview' => 'Преглед на страницата','Preview viewport' => 'Прозорец за предварителен преглед','Tablet' => 'Таблет','Desktop' => 'Работен плот','Preview width' => 'Ширина на предварителния преглед','Decrease width' => 'Намали ширината','Preview width in pixels' => 'Ширина на предварителния преглед в пиксели','Increase width' => 'Увеличаване на ширината','Preview as' => 'Преглед като','Guest' => 'Гост','Logged in' => 'Влязъл съм','Preview page' => 'Страница за предварително преглед','Expand preview for a closer look' => 'Разширете предварителния преглед, за да разгледате по-отблизо','Available with %s.' => 'Предлага се с %s.','Turn them on' => 'Включете ги','Optimizations for this page are turned off. %s to preview the page.' => 'Оптимизациите за тази страница са изключени. %s, за да видите страницата в предварителен преглед.','%s preview' => '%s – предварителен преглед','Isolated session · nothing is saved' => 'Изолирана сесия · нищо не се запазва','Usage tracking' => 'Проследяване на използването','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Изпращайте доклади за средата на сайта, които не съдържат чувствителна информация, за да помогнете на Fluid Checkout да подобри съвместимостта си. Докладите се изпращат само след като тази опция бъде активирана в настройките по-долу.','Send usage tracking reports to Fluid Checkout' => 'Изпращане на отчети за проследяване на използването към Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Тези отчети ни помагат да подобрим съвместимостта и поддръжката на вашия сайт и се изпращат седмично, когато тази функция е активирана.','No customer, admin user, or any other sensitive data is included in the reports.' => 'В отчетите не се включват данни за клиенти, администратори или каквито и да било други чувствителни данни.','Basic environment info' => 'Основна информация за средата','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Данни за WordPress, PHP, WooCommerce, темата и списъка с плъгини. Винаги се включват, когато отчитането е активирано. Помагат ни да разберем средата, в която работи вашият сайт.','Plugin settings' => 'Настройки на приставката','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Изпраща настройките на плъгина „Fluid Checkout“, за да улесни обработката на заявките за поддръжка и да ни помогне да разберем как използвате нашите плъгини.','Coming soon' => 'Очаквайте скоро','Sales metrics' => 'Показатели за продажбите','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Брой поръчки на месец и общи продажби за периода от една година преди инсталирането на Fluid Checkout до днес. Това ни помага да разберем дали печелите повече пари, когато нашите плъгини са инсталирани. Никога не се изпращат данни за клиенти или потребители.','Utilities' => 'Общи услуги','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Използвайте компонентите с падащо меню <code>TomSelect</code> вместо <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect е по-опростен компонент за избор чрез падащо меню, който е по-малко податлив на грешки в сравнение с Select2, като в същото време предлага същата функционалност.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Задава размера на шрифта в полетата на формулярите на 16px на страниците, оптимизирани от този плъгин, за да се избегне автоматичното увеличаване при взаимодействие с полетата на формулярите на малки устройства.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari и други браузъри може автоматично да увеличават мащаба на мобилните устройства, за да улеснят четенето на текста, когато размерът на шрифта е по-малък от 16px.','Enable script processing tracking on the browser console.' => 'Активирайте проследяването на обработката на скриптове в конзолата на браузъра.','Unminified assets' => 'Неоптимизирани ресурси','Google Maps scripts' => 'Скриптове за Google Maps','Do not remove duplicate Google Maps scripts' => 'Не премахвайте дублиращите се скриптове на Google Maps','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Когато тази опция е активирана, дублиращите се скриптове на Google Maps НЯМА да бъдат премахнати, което може да доведе до грешки и проблеми с производителността. Използвайте тази опция само при отстраняване на проблеми.','Widget areas' => 'Зони за джаджи','Last step on mobile' => 'Последна стъпка на мобилно устройство','Display widgets only at last step on mobile' => 'Показване на виджети само на последния етап при ползване на мобилни устройства','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Да се показват виджети с емблеми за доверие при плащане само при преглед на последната стъпка от процеса на плащане на мобилни устройства','Standard' => 'Стандартен','VAT number field' => 'Поле за номер по ДДС','Add a VAT number field to the billing form.' => 'Добавете поле за ДДС номер във формуляра за фактуриране.','Field label' => 'Етикет на полето','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Задайте наименованието на полето за ДДС номер (например „ДДС номер“). При многоезични уебсайтове е по-добре това поле да се остави празно и да се преведе оригиналният текст.','VAT Number' => 'ДДС номер','EU-VAT' => 'ДДС в ЕС','Enable the VAT number field to see more options' => 'Активирайте полето за ДДС номер, за да видите повече опции','VAT validation' => 'Проверка на ДДС','Validate VAT number field for EU-VAT during checkout' => 'Проверка на полето за ДДС номер за ДДС в ЕС при извършване на поръчката','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Проверява дали предоставеният ДДС номер е валиден и дали е регистриран в европейската база данни VIES (Система за обмен на информация за ДДС).','Shop VAT number' => 'ДДС номер на магазина','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'ДДС номерът на магазина, използван за заявка за валидиране на ДДС в ЕС и отпечатан върху фактурите. <br><strong>Настоятелно препоръчваме да добавите ДДС номера на вашия магазин</strong>, тъй като в противен случай резултатите от проверката в VIES може да не са валидни за счетоводни цели. <br>Например: <code>ATU99999999</code> или <code>EE999999999</code>.','Reverse charge' => 'Обратно начисляване','Apply reverse charge mechanism' => 'Прилагане на механизма за обратно начисляване','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Задайте данъчната ставка на нула и показвайте „Обратно начисляване“ във фактурите, когато ДДС-номерът на клиента е валиден. В зависимост от държавата, в която се намира магазинът, може да се наложи да се използва различен текст за „Обратно начисляване“.','Same country' => 'В същата държава','Apply reverse charge mechanism for transactions in the shop country:' => 'Прилагане на механизма за обратно начисляване за сделките в страната, в която се намира магазинът:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Позволява прилагането на механизма за обратно начисляване при сделки между фирми в същата държава, в която се намира магазина.','Reverse charge exceptions' => 'Изключения от механизма за обратно начисляване','Select additional countries to skip applying the reverse charge mechanism.' => 'Изберете допълнителни държави, за които да не се прилага механизмът за обратно начисляване.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'За поръчки от тези държави ще се начисляват данъци, дори когато е посочен валиден номер по ДДС.','Reverse charge label on invoices' => 'Етикет за обратно начисляване върху фактурите','Set the label of "reverse charge" on the checkout page and order details.' => 'Поставете етикета „обратна такса“ на страницата за плащане и в подробностите за поръчката.','Reverse charge text on invoices' => 'Текст за обратно начисляване във фактурите','Set the label of "reverse charge" text on invoices.' => 'Задайте надписа „обратна данъчна отговорност“ във фактурите.','Tax to be paid on reverse charge basis' => 'Данъкът се плаща по принципа на обратното начисляване','Company name' => 'Наименование на дружеството','Autocomplete company name from VAT number' => 'Автоматично попълване на името на фирмата въз основа на ДДС-номера','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Попълнете името на фирмата-фактуриращ субект въз основа на валидния ДДС номер, предоставен от клиента.','Company name editing' => 'Редактиране на името на фирмата','Allow editing of auto-filled company name' => 'Разрешаване на редактирането на автоматично попълненото име на фирмата','When enabled, customers can change the company name associated with the provided VAT number.' => 'Когато тази опция е активирана, клиентите могат да променят името на фирмата, свързано с предоставения номер по ДДС.','EU-VAT for digital goods' => 'ДДС на ЕС за цифрови стоки','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'От 1 януари 2015 г. бяха въведени промени в регламентите на ЕС за ДДС, отнасящи се до цифровите стоки, които засягат изключително транзакциите от типа „бизнес към потребител“ (B2C). ДДС върху цифровите стоки трябва да се изчислява въз основа на местонахождението на клиента, като е необходимо да се събират доказателства за това (IP адрес и адрес за фактуриране).','Tax classes for digital goods' => 'Данъчни категории за цифрови стоки','Select some tax classes' => 'Изберете някои данъчни категории','Location evidence' => 'Доказателства за местонахождението','Collect customer\'s location evidence' => 'Събиране на доказателства за местонахождението на клиента','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Запазва IP адреса и го сравнява с адреса за фактуриране на клиента. Клиентите трябва да потвърдят адреса си за фактуриране, като отбележат съответното поле на страницата за плащане, ако държавата, посочена в адреса за фактуриране, и тази от IP адреса не съвпадат.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Тази опция се управлява в Fluid Checkout. <a href="%s">Променете я в настройките на клиентските профили</a>.','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Тази опция се управлява в Fluid Checkout. Можете да я промените в раздела „Fluid Checkout“ > „Профили на клиенти“.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Тази опция се управлява в Fluid Checkout. Когато Fluid Checkout е активиран, адресът за доставка винаги се задава като „По подразбиране – адресът за доставка на клиента“. Клиентите все пак могат да посочат различни адреси за доставка и фактуриране по време на плащането.<br><br>Опция за настройка на адреса за фактуриране по подразбиране да бъде същият като адреса за доставка е налична в <a href="%s">настройките на Fluid Checkout</a>.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Тази опция се управлява в Fluid Checkout. Когато Fluid Checkout е активиран, местоназначението за доставка винаги е зададено на „По подразбиране – адрес за доставка на клиента“. Клиентите все пак могат да посочат различни адреси за доставка и фактуриране по време на плащането.<br><br>Опция за задаване на адреса за фактуриране по подразбиране да бъде същият като адреса за доставка е достъпна в WooCommerce > Настройки > Fluid Checkout.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Тези настройки са преместени в WP Admin > Fluid Checkout > Настройки.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Този раздел „Настройки“ на WooCommerce вече не се поддържа и ще бъде премахнат във версия 6.0 на Fluid Checkout.','Go to settings page' => 'Отиди на страницата с настройките','Hide this tab permanently' => 'Скрий този раздел завинаги','Site report preview' => 'Преглед на отчета за сайта','This is the data that would be included in the next site environment report based on your current settings.' => 'Това са данните, които биха били включени в следващия доклад за състоянието на обекта въз основа на текущите ви настройки.','Loading report preview...' => 'Зареждане на предварителен преглед на отчета...','Could not load the site report preview. Try again.' => 'Не успяхме да заредим предварителния преглед на отчета за сайта. Опитайте отново.','Could not send the site report. Try again.' => 'Не успях да изпратя отчета за сайта. Опитайте отново.','Site report sent successfully.' => 'Докладът за обекта беше изпратен успешно.','Enable and send now' => 'Активирай и изпрати сега','Close' => 'Затвори','A site report request is already in progress. Try again in a moment.' => 'В момента се обработва заявка за доклад за обекта. Опитайте отново след малко.','Site environment reporting is disabled.' => 'Отчитането на състоянието на сайта е деактивирано.','No site report data is available to send.' => 'Няма налични данни от отчети за обекти, които да бъдат изпратени.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Домейнът на този сайт не може да изпраща отчети за средата (с изключение на локалните домейни и домейните за разработка).','A site report was sent recently. Try again later.' => 'Наскоро беше изпратен доклад за обекта. Опитайте отново по-късно.','The site report could not be sent. Try again later.' => 'Докладът за сайта не можа да бъде изпратен. Опитайте отново по-късно.','Site environment reporting is not available.' => 'Отчетите за състоянието на обекта не са достъпни.','No site report data is available for the selected settings.' => 'За избраните настройки няма налични данни от отчета за обекта.','You are not allowed to manage site reports.' => 'Нямате право да управлявате отчетите на сайта.','PRO feature' => 'Функция PRO','Other plugins' => 'Други плъгини','Get only this add-on &mdash; %s' => 'Изтеглете само това разширение — %s','Install add-on' => 'Инсталиране на добавка','Upgrade to PRO &mdash; %s' => 'Преминете към PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Вземете %2$s</a>, за да отключите тези опции.','Add-on' => 'Допълнение','View documentation' => 'Преглед на документацията','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'За заявките е необходимо потребителят да е влязъл в системата на WordPress. Пропуснете user_id, за да използвате данните на текущия потребител, или посочете user_id, за да насочите заявката към друг акаунт, когато извикващият има право да редактира този потребител (право „edit_user“). Неавтентифицираните заявки връщат fc_api_forbidden. Невалиден user_id връща fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 с { "data": { ... } }, когато обработчикът върне полезен товар.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 с { "success": true }, когато няма полезен товар (например DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'При грешки се връща JSON-отговор за REST грешка в WordPress от WP_Error (код, съобщение, data.status). Кодовете за връзка използват префикса fc_api_*.','Forbidden access.' => 'Достъпът е забранен.','Target user was not found.' => 'Потребителят, към когото е адресирано съобщението, не беше намерен.','This feature is not available.' => 'Тази функция не е достъпна.','A required address field is missing.' => 'Липсва задължително поле за адрес.','Postcode or ZIP is invalid.' => 'Пощенският код или ZIP кодът е невалиден.','Phone number is invalid.' => 'Телефонният номер е невалиден.','State or county is invalid.' => 'Щатът или окръгът е невалиден.','Country is invalid or has no address fields.' => 'Страната е невалидна или няма полета за адрес.','The request could not be processed.' => 'Заявката не можа да бъде обработена.','Back to previous step' => 'Назад към предишната стъпка','Skip to settings' => 'Премини към настройките','Start over and return to the first guided setup step' => 'Започнете отначало и се върнете към първата стъпка от настройката с помощта на указанията','Start over' => 'Започни отначало','Please complete all sub-steps before continuing.' => 'Моля, изпълнете всички подстъпки, преди да продължите.','Expand' => 'Разгърни','Collapse' => 'Скрий','Skip' => 'Пропусни','Mark as complete' => 'Маркирай като завършено','Mark as incomplete' => 'Маркирай като незавършено','View full-size image: %s' => 'Виж изображението в пълен размер: %s','Full-size setup guide image' => 'Изображение на ръководството за настройка в пълен размер','Close image' => 'Затвори изображението','Fluid Checkout Guided Setup' => 'Настройка с помощта на „Fluid Checkout“','Welcome' => 'Добре дошли','Explore your checkout' => 'Разгледайте процеса на плащане','All set' => 'Всичко е готово','You do not have permission to access this page.' => 'Нямате право на достъп до тази страница.','Go to step %1$d: %2$s' => 'Премини към стъпка %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Това ръководство за настройка ще ви помогне да се запознаете с Fluid Checkout. Посочените по-долу стъпки засега са само примерни.','Continue to the next step when you are ready.' => 'Когато сте готови, преминете към следващата стъпка.','Open your store checkout to see Fluid Checkout in action.' => 'Отворете страницата за плащане в магазина си, за да видите как работи Fluid Checkout.','View checkout page' => 'Преглед на страницата за плащане','You can return to Fluid Checkout settings to continue configuring your store.' => 'Можете да се върнете към настройките на Fluid Checkout, за да продължите с конфигурирането на вашия магазин.','Review checkout and cart settings' => 'Преглед на настройките за плащане и кошницата','Explore add-ons from the dashboard' => 'Разгледайте добавките от таблото за управление','Finish & go to settings' => 'Завърши и премини към настройките','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Актуализирайте опцията за видимост на полето „Телефон за фактуриране“, като промените старата стойност, за да съответства на стандартите на WooCommerce.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Актуализирайте опцията за видимост на полето „Телефон за доставка“, като промените старата стойност, за да съответства на конвенциите на WooCommerce.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Копирайте настройката за цвета на фона на обобщението на поръчката в новата опция за цвета на фона на вторичната колона в дизайна „Split“.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Функцията за разширени полета за избор винаги е деактивирана при използване на плъгина Biteship.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'При използване на German Market позицията на бутона за подаване на поръчка винаги е зададена като „Под обобщението на поръчката“. Този плъгин изисква бутонът за подаване на поръчка и отметките за съгласие с правните условия да се показват под обобщението на поръчката.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'При използването на Germanized за WooCommerce позицията на бутона за потвърждаване на поръчката винаги се задава като „Под обобщението на поръчката“. Този плъгин изисква бутонът за потвърждаване на поръчката и отметъците за съгласие с правните условия да се показват под обобщението на поръчката.','Edit pickup locations' => 'Редактиране на местата за получаване','Use local pickup label from WooCommerce settings' => 'Използвайте етикет за локално вземане от настройките на WooCommerce','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Когато тази опция е активирана, надписът на опцията за самовземане при финализиране на поръчката съвпада със заглавието от настройките за мястото на самовземане в WooCommerce. Когато е деактивирана, надписът използва преводимия текст „Самовземане на място“ от Fluid Checkout.','Button label for applying coupon codesApply' => 'Направете заявка на','Checkout step titleContact' => 'Свържете се с','Checkout step titleShipping' => 'Доставка','Checkout step titleBilling' => 'Фактуриране','Checkout step titlePayment' => 'Плащане','Checkout substep change link labelChange' => 'Промяна','Checkout substep save link labelSave changes' => 'Запазване на промените','Substep review textNone.' => 'Няма.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Не е избрано изображение.','Settings sectionCart' => 'Количка','Settings sectionOrder pay' => 'Плащане на поръчката','Settings sectionThank you' => 'Благодаря ви','Settings section titleIntegrations' => 'Интеграции','Settings section titleLicense keys' => 'Лицензионни ключове','Captcha positionBefore place order section' => 'Преди да поставите поръчка раздел','Captcha positionBefore place order button' => 'Преди бутона "Поръчай','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Затвори','Log in link label at checkout contact stepLog in' => 'Влезте в системата','Log in separator label at for when guest checkout is disabledOr continue below' => 'Или продължете по-долу','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Или продължете като гост','Clear image selection on admin pages.Remove image' => 'Премахване на изображението','shipping packagesShipping %d' => 'Доставка %d','shipping packagesShipping' => 'Доставка','Used as fallback for "Proceed to next step" button labelnext step' => 'следваща стъпка','Substep review checkbox valueYes' => 'Да','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'Джон','Dummy customer last name in the admin previewDoe' => 'Елен','Dummy customer company in the admin previewExample Company' => 'Примерна компания','Dummy customer street address in the admin preview123 Main Street' => 'ул. „Мейн“ № 123','Dummy customer city in the admin previewAnytown' => 'Някое градче','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Моля, оставете пратката пред входната врата.','Dummy product name in the admin previewBeanie' => 'Шапка с козирка','Dummy product name in the admin previewCap' => 'Капачка','Dummy product name in the admin previewT-Shirt' => 'Тениска','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Получихме поръчката Ви и ще Ви уведомим, когато бъде изпратена.','Dummy download in the admin previewUser guide' => 'Ръководство за ползване','Google Places API versionsPlaces API (New)' => 'API за места (ново)','Google Places API versionsPlaces API (Legacy)' => 'API за места (стара версия)','Brasil API versionsVersion 1' => 'Версия 1','Brasil API versionsVersion 2' => 'Версия 2','Delayed account creation benefits placeholder text✔ Checkout faster next time
